#!/usr/bin/env node
/*
 * Research-only analyzer.
 *
 * It consumes a strict-PIT source report generated by
 * research-true-pit-strategies.js. Every constituent list was generated from
 * the raw-data prefix ending at D-1. This script only combines those already
 * frozen lists; it never reads the actual result when selecting exclusions.
 */
const fs = require('fs');
const path = require('path');

const ALL_NUMBERS = Array.from({ length: 100 }, (_, number) => number);

function parseArgs() {
    const args = new Map(process.argv.slice(2).map(arg => {
        const [key, value] = arg.replace(/^--/, '').split('=');
        return [key, value === undefined ? '1' : value];
    }));
    const reportFile = args.get('reportFile');
    const liveSnapshotFile = args.get('liveSnapshotFile');
    const fallbackReportFile = args.get('fallbackReportFile');
    if (!reportFile && !liveSnapshotFile) {
        throw new Error('Cần truyền --reportFile=<strict-pit-source> hoặc --liveSnapshotFile=<cached_milestone20y_live_predictions.json>.');
    }
    if (reportFile && liveSnapshotFile) {
        throw new Error('Khi có snapshot, dùng --fallbackReportFile=<strict-pit-source> thay cho --reportFile.');
    }
    if (fallbackReportFile && !liveSnapshotFile) {
        throw new Error('--fallbackReportFile chỉ dùng cùng --liveSnapshotFile.');
    }
    const csv = value => String(value || '')
        .split(',')
        .map(item => item.trim())
        .filter(Boolean);
    return {
        reportFile: reportFile ? path.resolve(reportFile) : null,
        liveSnapshotFile: liveSnapshotFile ? path.resolve(liveSnapshotFile) : null,
        fallbackReportFile: fallbackReportFile ? path.resolve(fallbackReportFile) : null,
        minBet: Number(args.get('minBet') || 10),
        maxBet: Number(args.get('maxBet') || 20),
        targets: csv(args.get('targets')).map(Number).filter(Number.isInteger),
        moc20Strategies: csv(args.get('moc20Strategies')),
        d1Methods: csv(args.get('d1Methods')),
        // Distinguish an omitted filter (include every available source) from
        // an explicit empty filter (--d1Methods=, include none).  This matters
        // when validating a Mốc 20 năm-only combination.
        moc20StrategiesSpecified: args.has('moc20Strategies'),
        d1MethodsSpecified: args.has('d1Methods'),
        fixedHolds: String(args.get('fixedHolds') || '60,65,70,75,80')
            .split(',')
            .map(Number)
            .filter(value => Number.isInteger(value) && value > 0 && value < 100),
        betPerNumberK: Number(args.get('betPerNumberK') || 1000),
        winMultiplier: Number(args.get('winMultiplier') || 84)
    };
}

function toRecomputedRows(payload, options) {
    return (payload.rows || []).map(row => ({
        date: row.date,
        actual: Number(row.actual),
        sources: buildSources(row, options),
        sourceKind: 'recomputed-strict-pit'
    }));
}

function toSnapshotRows(payload, options) {
    return (payload.predictions || [])
        .filter(row => row?.predictionIsoDate && row?.actualSpecial !== null && row?.actualSpecial !== undefined)
        .map(row => ({
            date: row.predictionIsoDate,
            actual: Number(row.actualSpecial),
            sources: buildSnapshotSources(row, options),
            sourceKind: 'published-live-snapshot',
            snapshotGeneratedAt: row.generatedAt || payload.generatedAt || null,
            snapshotBaseline: row.baseline || null
        }));
}

function mergeSnapshotWithFallback(snapshotRow, fallbackRow) {
    if (!snapshotRow) return fallbackRow;
    if (!fallbackRow) return snapshotRow;

    // A published source is immutable.  Recomputed strict-PIT evidence is
    // allowed only to fill strategy/hold entries that did not exist yet in an
    // early snapshot, never to replace an entry that was actually published.
    const sourcesByKey = new Map(fallbackRow.sources.map(source => [sourceKey(source), source]));
    for (const source of snapshotRow.sources) {
        const compatibleFallbackKey = `moc20:${source.id}:hold${source.target}`;
        sourcesByKey.delete(compatibleFallbackKey);
        sourcesByKey.set(sourceKey(source), source);
    }
    const sources = [...sourcesByKey.values()];
    const hasRecomputedFill = sources.some(source => source.source !== 'moc20-live-snapshot');
    return {
        ...snapshotRow,
        sources,
        sourceKind: hasRecomputedFill
            ? 'snapshot-plus-recomputed-strict-pit'
            : 'published-live-snapshot'
    };
}

function isoWeek(date) {
    const value = new Date(`${date}T00:00:00Z`);
    value.setUTCDate(value.getUTCDate() + 4 - (value.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(value.getUTCFullYear(), 0, 1));
    const week = Math.ceil((((value - yearStart) / 86400000) + 1) / 7);
    return `${value.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
}

function buildSources(row, options) {
    const sources = [];
    for (const [target, strategies] of Object.entries(row.strategiesByTarget || {})) {
        for (const [id, numbers] of Object.entries(strategies || {})) {
            if (options.targets.length > 0 && !options.targets.includes(Number(target))) continue;
            if (options.moc20StrategiesSpecified && !options.moc20Strategies.includes(id)) continue;
            if (!Array.isArray(numbers) || numbers.length < options.minBet || numbers.length > options.maxBet) continue;
            sources.push({ source: 'moc20', id, target: Number(target), numbers });
        }
    }
    for (const [target, strategies] of Object.entries(row.rollingStrategiesByTarget || {})) {
        for (const [id, method] of Object.entries(strategies || {})) {
            const numbers = method?.betNumbers;
            if (options.targets.length > 0 && !options.targets.includes(Number(target))) continue;
            if (options.d1MethodsSpecified && !options.d1Methods.includes(id)) continue;
            if (!Array.isArray(numbers) || numbers.length < options.minBet || numbers.length > options.maxBet) continue;
            sources.push({ source: 'd1', id, target: Number(target), numbers });
        }
    }
    return sources;
}

function buildSnapshotSources(row, options) {
    const sources = [];
    for (const [id, strategy] of Object.entries(row.strategies || {})) {
        if (options.moc20StrategiesSpecified && !options.moc20Strategies.includes(id)) continue;
        for (const [target, prediction] of Object.entries(strategy.holds || {})) {
            if (options.targets.length > 0 && !options.targets.includes(Number(target))) continue;
            const numbers = (prediction?.betNumbers || []).map(Number);
            if (numbers.length < options.minBet || numbers.length > options.maxBet) continue;
            sources.push({ source: 'moc20-live-snapshot', id, target: Number(target), numbers });
        }
    }
    return sources;
}

function scoreNumbers(sources) {
    const score = ALL_NUMBERS.map(number => ({ number, votes: 0, weightedVotes: 0, sources: [] }));
    for (const source of sources) {
        // A smaller betting list is a narrower negative signal, but no result
        // information is used here. The 10-20 range maps to weights 11..1.
        const weight = Math.max(1, 21 - source.numbers.length);
        for (const rawNumber of source.numbers) {
            const number = Number(rawNumber);
            if (!Number.isInteger(number) || number < 0 || number > 99) continue;
            score[number].votes += 1;
            score[number].weightedVotes += weight;
            score[number].sources.push(`${source.source}:${source.id}:hold${source.target}`);
        }
    }
    return score;
}

function sortByEvidence(rows) {
    return rows.slice().sort((left, right) =>
        right.votes - left.votes ||
        right.weightedVotes - left.weightedVotes ||
        left.number - right.number
    );
}

function profitFor(betNumbers, actual, options) {
    const stakeK = betNumbers.length * options.betPerNumberK;
    const hit = betNumbers.includes(actual);
    return {
        hit,
        stakeK,
        profitK: hit
            ? (options.winMultiplier * options.betPerNumberK) - stakeK
            : -stakeK
    };
}

function createSummary() {
    return { days: 0, wins: 0, losses: 0, profitK: 0, stakeK: 0, betCount: 0 };
}

function addSummary(summary, detail) {
    summary.days += 1;
    summary.wins += detail.hit ? 1 : 0;
    summary.losses += detail.hit ? 0 : 1;
    summary.profitK += detail.profitK;
    summary.stakeK += detail.stakeK;
    summary.betCount += detail.betNumbers.length;
}

function finalizeSummary(summary) {
    return {
        ...summary,
        averageBetCount: summary.days ? summary.betCount / summary.days : 0,
        hitRate: summary.days ? summary.wins / summary.days : 0,
        roi: summary.stakeK ? summary.profitK / summary.stakeK : 0
    };
}

function summarize(rows, methodId) {
    const overall = createSummary();
    const weekly = new Map();
    const monthly = new Map();
    let currentWin = 0;
    let currentLoss = 0;
    let longestWin = 0;
    let longestLoss = 0;
    for (const row of rows) {
        const detail = row.methods[methodId];
        if (!detail || detail.eligible === false) continue;
        addSummary(overall, detail);
        const week = isoWeek(row.date);
        const month = row.date.slice(0, 7);
        if (!weekly.has(week)) weekly.set(week, createSummary());
        if (!monthly.has(month)) monthly.set(month, createSummary());
        addSummary(weekly.get(week), detail);
        addSummary(monthly.get(month), detail);
        if (detail.hit) {
            currentWin += 1;
            currentLoss = 0;
            longestWin = Math.max(longestWin, currentWin);
        } else {
            currentLoss += 1;
            currentWin = 0;
            longestLoss = Math.max(longestLoss, currentLoss);
        }
    }
    return {
        ...finalizeSummary(overall),
        longestWin,
        longestLoss,
        weekly: Array.from(weekly.entries()).map(([period, summary]) => ({ period, ...finalizeSummary(summary) })),
        monthly: Array.from(monthly.entries()).map(([period, summary]) => ({ period, ...finalizeSummary(summary) }))
    };
}

function sourceKey(source) {
    return `${source.source}:${source.id}:hold${source.target}`;
}

function buildWalkForwardMethods(rows, options) {
    const windows = [30, 60, 90];
    const counts = [5, 10, 15];
    const dailySourceResults = rows.map(row => Object.fromEntries(
        row.sources.map(source => [sourceKey(source), {
            numbers: source.numbers,
            hit: source.numbers.includes(row.actual)
        }])
    ));
    for (let index = 0; index < rows.length; index++) {
        const row = rows[index];
        for (const window of windows) {
            const start = Math.max(0, index - window);
            const priorDays = dailySourceResults.slice(start, index);
            const current = dailySourceResults[index];
            const rankings = Object.keys(current).map(key => {
                let hits = 0;
                let observations = 0;
                for (const day of priorDays) {
                    if (!day[key]) continue;
                    observations += 1;
                    hits += day[key].hit ? 1 : 0;
                }
                return { key, hits, observations, hitRate: observations ? hits / observations : null };
            }).filter(row => row.observations === window);
            rankings.sort((left, right) =>
                left.hitRate - right.hitRate ||
                left.hits - right.hits ||
                left.key.localeCompare(right.key)
            );
            for (const count of counts) {
                const id = `walkForwardLowHitW${window}K${count}`;
                if (rankings.length < count) {
                    row.methods[id] = { eligible: false, betNumbers: [], excludedNumbers: [] };
                    continue;
                }
                const selected = rankings.slice(0, count);
                const excluded = new Set();
                for (const selectedSource of selected) {
                    for (const number of current[selectedSource.key].numbers) excluded.add(number);
                }
                const betNumbers = ALL_NUMBERS.filter(number => !excluded.has(number));
                row.methods[id] = {
                    eligible: true,
                    excludedNumbers: [...excluded].sort((a, b) => a - b),
                    betNumbers,
                    selectedSources: selected,
                    ...profitFor(betNumbers, row.actual, options)
                };
            }
        }
    }
}

function main() {
    const options = parseArgs();
    const primaryPayload = JSON.parse(fs.readFileSync(
        options.reportFile || options.liveSnapshotFile,
        'utf8'
    ));
    const fallbackPayload = options.fallbackReportFile
        ? JSON.parse(fs.readFileSync(options.fallbackReportFile, 'utf8'))
        : null;
    const sourceRows = options.liveSnapshotFile
        ? (() => {
            const snapshots = toSnapshotRows(primaryPayload, options)
                .filter(row => row.sources.length > 0);
            const snapshotByDate = new Map(snapshots.map(row => [row.date, row]));
            const fallbackByDate = new Map(toRecomputedRows(fallbackPayload || {}, options)
                .filter(row => row.sources.length > 0)
                .map(row => [row.date, row]));
            const dates = [...new Set([...fallbackByDate.keys(), ...snapshotByDate.keys()])].sort();
            return dates.map(date => mergeSnapshotWithFallback(
                snapshotByDate.get(date),
                fallbackByDate.get(date)
            ));
        })()
        : toRecomputedRows(primaryPayload, options).filter(row => row.sources.length > 0);
    const rows = sourceRows.map(row => {
        const sources = row.sources;
        const evidence = sortByEvidence(scoreNumbers(sources));
        const methods = {};
        const createMethod = (id, excluded) => {
            const excludedSet = new Set(excluded);
            const betNumbers = ALL_NUMBERS.filter(number => !excludedSet.has(number));
            methods[id] = {
                excludedNumbers: [...excludedSet].sort((a, b) => a - b),
                betNumbers,
                sourceCount: sources.length,
                ...profitFor(betNumbers, row.actual, options)
            };
        };
        createMethod('smallDanUnion', evidence.filter(row => row.votes >= 1).map(row => row.number));
        createMethod('smallDanConsensus2', evidence.filter(row => row.votes >= 2).map(row => row.number));
        createMethod('smallDanConsensus3', evidence.filter(row => row.votes >= 3).map(row => row.number));
        for (const hold of options.fixedHolds) {
            createMethod(`smallDanRankHold${hold}`, evidence.slice(0, hold).map(row => row.number));
        }
        return {
            date: row.date,
            actual: row.actual,
            sources: sources.map(source => ({ ...source, numbers: source.numbers.slice() })),
            evidence,
            ...(row.snapshotGeneratedAt ? { snapshotGeneratedAt: row.snapshotGeneratedAt } : {}),
            ...(row.snapshotBaseline ? { snapshotBaseline: row.snapshotBaseline } : {}),
            sourceKind: row.sourceKind,
            methods
        };
    });
    buildWalkForwardMethods(rows, options);
    const methodIds = [...new Set(rows.flatMap(row => Object.keys(row.methods)))];
    const summaries = Object.fromEntries(methodIds.map(id => [id, summarize(rows, id)]));
    const ranking = Object.entries(summaries)
        .map(([id, summary]) => ({ id, ...summary }))
        .sort((left, right) => right.profitK - left.profitK || right.hitRate - left.hitRate);
    const report = {
        generatedAt: new Date().toISOString(),
        methodology: [
            options.liveSnapshotFile && options.fallbackReportFile
                ? 'Ngày có snapshot Mốc 20 năm dùng đúng snapshot đã phát hành và khóa bất biến; chỉ ngày thiếu snapshot mới dùng strict PIT tái tính từ raw prefix D-1.'
                : (options.liveSnapshotFile
                    ? 'Mỗi ngày dùng đúng snapshot Mốc 20 năm đã phát hành và khóa bất biến; không tái tính dàn từ code hiện tại.'
                    : 'Mỗi ngày chỉ dùng dàn 10-20 số đã sinh strict point-in-time từ raw prefix đến D-1.'),
            options.liveSnapshotFile
                ? 'Nguồn chỉ gồm các strategy Mốc 20 năm có mặt trong snapshot đã chốt.'
                : 'Nguồn gồm các strategy Mốc 20 năm và bốn strategy D-1 có implementation production: chainSmallFirst, chainBlockFirst, dedupEdge75, deParallelBlock85Small65.',
            'Các số xuất hiện trong dàn đánh nhỏ được xem là tín hiệu loại; actual không được dùng khi xây danh sách loại.',
            'smallDanUnion là phép hợp trực tiếp; consensus yêu cầu >=2 hoặc >=3 nguồn; Rank Hold chọn đúng N số có nhiều phiếu nhất.'
        ].join(' '),
        strictPointInTime: true,
        sourceKind: options.liveSnapshotFile && options.fallbackReportFile
            ? 'snapshot-with-recomputed-strict-pit-fallback'
            : (options.liveSnapshotFile ? 'published-live-snapshot' : 'recomputed-strict-pit'),
        sourceReport: options.reportFile || options.liveSnapshotFile,
        fallbackReport: options.fallbackReportFile || null,
        sourceFingerprint: primaryPayload.fingerprint || null,
        fallbackFingerprint: fallbackPayload?.fingerprint || null,
        sourceBreakdown: {
            publishedSnapshotDays: rows.filter(row => row.sourceKind === 'published-live-snapshot').length,
            recomputedStrictPitDays: rows.filter(row => row.sourceKind === 'recomputed-strict-pit').length,
            snapshotWithStrictPitFillDays: rows.filter(row => row.sourceKind === 'snapshot-plus-recomputed-strict-pit').length
        },
        options,
        range: { start: rows[0]?.date || null, end: rows.at(-1)?.date || null, days: rows.length },
        ranking,
        summaries,
        rows
    };
    const outputPath = path.join(
        process.cwd(),
        'reports',
        `small_dan_union_exclusion_${new Date().toISOString().replace(/[:.]/g, '-')}.json`
    );
    fs.writeFileSync(outputPath, JSON.stringify(report, null, 2));
    console.log(JSON.stringify({
        outputPath,
        range: report.range,
        ranking: ranking.map(row => ({
            id: row.id,
            days: row.days,
            wins: row.wins,
            hitRate: row.hitRate,
            averageBetCount: row.averageBetCount,
            profitK: row.profitK,
            roi: row.roi,
            longestWin: row.longestWin,
            longestLoss: row.longestLoss
        }))
    }, null, 2));
}

main();
